import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    # We only need k=3 here
    if k == 3:
        return n * (n - 1) * (n - 2) // 6

    # General case (though not strictly needed for this problem)
    return math.comb(n, k)

def min_monochromatic_triangles(n):
    """
    Calculates the minimum number of monochromatic triangles guaranteed 
    in K_n, assuming all possible triangles are formed.
    The minimum occurs when the number of red (r) and blue (b) vertices are closest.
    """
    if n < 3:
        return 0

    min_count = float('inf')

    # Iterate through all possible partitions (r, b) such that r + b = n
    # We only need to check r up to n//2 due to symmetry
    for r in range(n // 2 + 1):
        b = n - r

        # Count red triangles and blue triangles
        count = combinations(r, 3) + combinations(b, 3)

        if count < min_count:
            min_count = count

    return min_count

# Check n from 1 to 7
results = {}
print("--- Checking n = 1 to 7 ---")
for n in range(1, 8):
    min_count = min_monochromatic_triangles(n)
    results[n] = min_count
    print(f"n={n}: Minimum monochromatic triangles guaranteed = {min_count}")

# Find the smallest n such that the minimum is >= 2
smallest_n = None
for n, count in results.items():
    if count >= 2:
        smallest_n = n
        break

print(f"\nSmallest n >= 2: {smallest_n}")

